:root {
  --paper: #fffdf8;
  --ink: #263238;
  --line: #d7d0c4;
  --plum: #75445d;
}

.dropoff-badge {
  width: 440px;
  box-sizing: border-box;
  padding: 18px 20px;
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 18px;
}

.dropoff-badge header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.hanger {
  font-size: 30px;
}

.dropoff-badge h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.dropoff-badge p {
  margin: 4px 0 0;
  color: var(--plum);
}

.token {
  color: var(--plum);
  font-size: 18px;
  font-weight: 700;
}
